        uint256 finalContractBalance = address(token).balance;

        // Verify ETH transfer
        assertEq(finalContractBalance, 0, "Contract ETH not drained");
        assertEq(
            finalOwnerBalance, 
            initialOwnerBalance + initialETH,
            "Owner did not receive ETH"
        );
    }
}
